#!/usr/bin/env python3
"""E12 task 5, done properly: subtract the IDEAL generated by the univariate image criteria.

`explain_n16.py` decides whether a relation is univariate by asking if it lies in the span of
monomials that touch only t0 or only t1.  At degree 3 that is enough.  At degree **4** it is not:
if g = Tr(t1^{-r1}) is a cubic relation, then every product `g * t0_i` is a quartic relation which
touches both blocks yet is not a cross-S-box relation at all — it is a multiple of a univariate
one.  Counting those as "genuine cross relations" would manufacture a Gate-1-relevant finding out
of nothing.

This script therefore compares two spaces of Boolean polynomials of degree <= deg on the joint
graph {(t0, t1)} of the two first-layer S-boxes:

    R = all relations of degree <= deg            (dim = #monomials - rank of the point matrix)
    C = the degree-<= deg part of the ideal generated by the image criteria
        g_i = Tr(t_i^{-r_i}),  i = 0, 1,  i.e. span{ m * g_i : deg(m * g_i) <= deg }

C is contained in R, so `dim R - dim C` is the number of genuine cross-S-box relations of degree
<= deg.  Everything is exact: g_i is obtained as the Moebius (ANF) transform of its truth table, so
its Boolean degree is measured rather than assumed.

Usage:
  python3 server/jobs/e12_criteria_subtract.py N [--deg 4] [--seed 1] [--backend sage]
                                               [--csv E12_server_criteria_subtract.csv]
"""
import argparse
import itertools
import os
import sys
import time
from math import comb, gcd

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), "..", ".."))
_EXP = os.path.join(ROOT, "experiments")
for p in [os.path.join(ROOT, "src"), os.path.join(ROOT, "legacy"), _EXP]:
    if p not in sys.path:
        sys.path.insert(0, p)

from _common import record                                          # noqa: E402
from aim3_lab import F, sbox, rand_unit_lu, apply_mat, rank_gf2     # noqa: E402
from aim3.boolmac_export import rank_sparse_sage                    # noqa: E402

SCRATCH = os.environ.get("AIM3_SCRATCH")


def anf(truth, n):
    """Moebius transform: truth table (list of 2^n bits) -> {monomial bitmask: 1}."""
    a = list(truth)
    step = 1
    while step < (1 << n):
        for i in range(1 << n):
            if i & step:
                a[i] ^= a[i ^ step]
        step <<= 1
    return {m for m in range(1 << n) if a[m]}


def criterion_anf(fld, e, n, shift):
    """ANF of t -> Tr(t^{-r}) as monomial bitmasks over the n variables starting at bit `shift`.

    The value at t = 0 is irrelevant (the graph never contains it) and is set to 0; a different
    choice would only change the coefficient of the single degree-n monomial.
    """
    q1 = fld.q - 1
    rr = pow((1 << e) - 1, -1, q1)
    tt = [0] * fld.q
    for t in range(1, fld.q):
        tt[t] = fld.trace(fld.pw(t, (-rr) % q1))
    ms = anf(tt, n)
    return {sum(1 << (shift + i) for i in range(n) if (m >> i) & 1) for m in ms}


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("n", type=int)
    ap.add_argument("--deg", type=int, default=4)
    ap.add_argument("--seed", type=int, default=1)
    ap.add_argument("--backend", choices=["python", "sage"], default="sage")
    ap.add_argument("--csv", default="E12_server_criteria_subtract.csv")
    a = ap.parse_args()
    n, deg = a.n, a.deg
    t_start = time.time()

    # identical instance to cross_relations.py / explain_n16.py
    import random
    rng = random.Random(a.seed)
    fld = F(n)
    es = [e for e in range(3, n - 1) if gcd(e, n) == 1][:2]
    A0, A1 = rand_unit_lu(n, rng), rand_unit_lu(n, rng)
    b0, b1 = rng.randrange(fld.q), rng.randrange(fld.q)
    pts = []
    for pt in range(fld.q):
        x0 = apply_mat(A0, pt, n) ^ b0
        x1 = apply_mat(A1, pt, n) ^ b1
        if x0 == 0 or x1 == 0:
            continue
        pts.append(sbox(fld, x0, es[0]) | (sbox(fld, x1, es[1]) << n))
    nv = 2 * n
    print(f"# params: n={n} deg={deg} seed={a.seed} exps={es} backend={a.backend}")
    print(f"{len(pts)} graph points, {nv} variables, "
          f"C({nv},<={deg}) = {sum(comb(nv, d) for d in range(deg+1))} monomials")

    ms = []
    for d in range(deg + 1):
        ms.extend(itertools.combinations(range(nv), d))
    masks = [sum(1 << i for i in m) for m in ms]
    KIDX = {msk: k for k, msk in enumerate(masks)}
    ncols = len(ms)

    # ---- dim R
    def idx_rows():
        for p in pts:
            supp = [i for i in range(nv) if (p >> i) & 1]
            out = []
            for d in range(min(deg, len(supp)) + 1):
                for c in itertools.combinations(supp, d):
                    out.append(KIDX[sum(1 << i for i in c)])
            yield out
    t0 = time.time()
    if a.backend == "sage":
        rk = rank_sparse_sage(idx_rows(), ncols, workdir=SCRATCH, tag=f"e12sub_n{n}_d{deg}")
    else:
        rk, _ = rank_gf2([sum(1 << KIDX[m] for m in
                              (sum(1 << i for i in c)
                               for d in range(deg + 1)
                               for c in itertools.combinations(
                                   [i for i in range(nv) if (p >> i) & 1], d)))
                          for p in pts])
    dimR = ncols - rk
    print(f"   dim R (all relations of degree <= {deg}) = {ncols} - {rk} = {dimR} "
          f"({time.time()-t0:.1f}s)")

    # ---- the criteria and the ideal they generate, truncated at degree deg
    crit, critinfo = [], []
    for i, e in enumerate(es):
        g = criterion_anf(fld, e, n, i * n)
        gdeg = max((m.bit_count() for m in g), default=0)
        vanishes = True
        for p in pts:                      # exactness check: g must vanish on every graph point
            s = 0
            for m in g:
                if p & m == m:
                    s ^= 1
            if s:
                vanishes = False
                break
        wt = n - pow(e, -1, n)
        print(f"   criterion g_{i} = Tr(t{i}^-r_{i}): {len(g)} ANF terms, Boolean degree {gdeg} "
              f"(wt(-r_{i}) = {wt}), vanishes on the graph: {vanishes}")
        critinfo.append(dict(i=i, e=e, terms=len(g), degree=gdeg, wt=wt, vanishes=vanishes))
        if vanishes and gdeg <= deg:
            crit.append((i, g, gdeg))

    rows = []
    nprod = 0
    for i, g, gdeg in crit:
        room = deg - gdeg
        for d in range(room + 1):
            for mult in itertools.combinations(range(nv), d):
                mu = 0
                for v in mult:
                    mu |= 1 << v
                acc = set()
                for m in g:
                    acc ^= {m | mu}
                if not acc or any(x.bit_count() > deg for x in acc):
                    continue
                rows.append(sorted(KIDX[x] for x in acc))
                nprod += 1
    if rows:
        rkC = (rank_sparse_sage(iter(rows), ncols, workdir=SCRATCH, tag=f"e12crit_n{n}_d{deg}",
                                verbose=False)
               if a.backend == "sage" else
               rank_gf2([sum(1 << k for k in r) for r in rows])[0])
    else:
        rkC = 0
    dimC = rkC
    genuine = dimR - dimC
    print(f"   dim C (multiples of the criteria, {nprod} products) = {dimC}")
    print(f"   => genuine cross-S-box relations of degree <= {deg}: {dimR} - {dimC} = "
          f"**{genuine}**")
    if genuine == 0:
        print(f"   => claim K holds at degree {deg}: every relation is a multiple of a univariate "
              f"image criterion")
    record(a.csv, dict(n=n, deg=deg, seed=a.seed, exps=";".join(map(str, es)),
                       npoints=len(pts), monomials=ncols, dim_R=dimR, dim_C=dimC,
                       n_products=nprod, genuine_cross=genuine,
                       crit0_degree=critinfo[0]["degree"], crit1_degree=critinfo[1]["degree"],
                       crit0_wt=critinfo[0]["wt"], crit1_wt=critinfo[1]["wt"],
                       crit0_vanishes=critinfo[0]["vanishes"], crit1_vanishes=critinfo[1]["vanishes"]),
           seconds=time.time() - t_start, tier="B")


if __name__ == "__main__":
    main()
